function shell(content,{native=false,portClass=''}={}){return `<div class="scroll-lab"><div class="scroll-window ${portClass}" tabindex="0" aria-label="見本の中を上下にスクロール。下のスライダーでも操作できます。">${native?content:`<div class="scroll-road"><div class="scroll-scene">${content}<span class="scroll-hint">SCROLL ↕</span></div></div>`}</div><label class="scroll-control"><span>位置</span><input class="scroll-range" type="range" min="0" max="100" value="0" aria-label="見本のスクロール位置"><output class="scroll-output">0%</output></label></div>`}
