// 04. A scene remains pinned while its explanatory content advances.
add('pinned-story','Pinned storytelling','留まる画面で話を進める','見本をその場に留め、スクロールに沿って説明を切り替えます。','工程や、順序のある説明を見せる場面。','position: stickyで見本を留め、章の切り替えをJavaScriptで行っています。',['ピン留め','sticky','pin','ストーリー','スクロールテリング'],shell('<div class="pin-story"><span class="pin-number">01</span><div><b class="pin-title">見つける。</b><p class="pin-copy">気になる表現に出会う。</p><i class="pin-step">● ○ ○</i></div></div>'),'.sample .pin-story{display:flex;gap:20px;align-items:center;padding:18px}.sample .pin-number{font:900 68px Arial;letter-spacing:-.08em;color:#b1b1b1}.sample .pin-title{font-size:20px;white-space:nowrap}.sample .pin-copy{font-size:10px;line-height:1.7;margin:8px 0}.sample .pin-step{font:9px monospace;letter-spacing:3px;font-style:normal}',(p,c)=>{const n=Math.min(2,Math.floor(p*3)),titles=['見つける。','名前を知る。','使ってみる。'],copy=['気になる表現に出会う。','仕組みを触って理解する。','自分の制作へ持ち帰る。'];c.root.querySelector('.pin-number').textContent=String(n+1).padStart(2,'0');c.root.querySelector('.pin-title').textContent=titles[n];c.root.querySelector('.pin-copy').textContent=copy[n];c.root.querySelector('.pin-step').textContent=[0,1,2].map(i=>i===n?'●':'○').join(' ')},stickySource);
