add('horizontal-track','Vertical-to-horizontal scroll','縦の操作で横へ進む','見本の中を縦にスクロールすると、横並びの面が移動します。','短いギャラリーや、横方向につながる物語。','縦スクロールを取り上げず、独立した見本の中だけで連動させています。',['横スクロール','horizontal','横移動','ギャラリー'],shell('<div class="horizontal-track"><div><small>CHAPTER 01</small><b>look.</b></div><div><small>CHAPTER 02</small><b>touch.</b></div><div><small>CHAPTER 03</small><b>make.</b></div></div>'),'.sample .horizontal-track{position:absolute;inset:0 auto 0 0;width:300%;height:100%;display:flex}.sample .horizontal-track>div{flex:0 0 33.333333%;height:100%;padding:24px;display:flex;flex-direction:column;justify-content:center;gap:9px;background:#ededed}.sample .horizontal-track>div:nth-child(2){background:#bcbcbc}.sample .horizontal-track>div:nth-child(3){background:#393939;color:#fff}.sample .horizontal-track small{font:8px monospace;letter-spacing:.12em}.sample .horizontal-track b{font:900 46px Arial;letter-spacing:-.07em}',(p,c)=>{const rail=c.root.querySelector('.horizontal-track'),w=c.root.querySelector('.scroll-scene').clientWidth;const n=c.reduced?Math.min(2,Math.floor(p*3))/2:p;rail.style.transform=`translateX(${-n*w*2}px)`},scrollSource);
