// 10. Meaningful reading-progress UI on a genuinely scrolling article.
add('reading-ring','Reading progress ring','読む進みを円で示す','見本の文章を読み進めると、円形の進捗が満たされます。','読み物や、複数段階の説明の進み具合。','進捗は見本内のスクロール量です。実際に読んだ割合を測っているわけではありません。',['進捗','progress','読了','円','読み物'],shell('<header class="reading-head"><b>読む、<br>進む。</b><div class="reading-ring"><svg viewBox="0 0 70 70" aria-hidden="true"><circle cx="35" cy="35" r="27" fill="none" stroke="#d6d6d6" stroke-width="5"/><circle class="reading-stroke" cx="35" cy="35" r="27" fill="none" stroke="#414141" stroke-width="5" transform="rotate(-90 35 35)"/></svg><output class="reading-value">0</output></div></header><article class="reading-copy"><p>ここは、スクロールを試すための短い読み物です。</p><p>動きには、目を引く役割だけでなく、現在地を知らせる役割もあります。</p><p>今どこにいて、どこまで進んだのか。小さな手がかりが、画面の理解を助けます。</p><p>最後まで進むと、円が満たされます。</p><b>END OF THE SAMPLE</b></article>',{native:true}),'.sample .reading-head{position:sticky;top:0;z-index:1;background:#f1f1f1;border-bottom:1px solid #d6d6d6;padding:14px 18px;display:flex;align-items:center;justify-content:space-between;gap:14px}.sample .reading-head>b{font-size:24px;letter-spacing:-.05em;line-height:1.05}.sample .reading-ring{width:60px;height:60px;position:relative}.sample .reading-ring svg{width:100%;height:100%}.sample .reading-value{position:absolute;inset:0;display:grid;place-items:center;font:12px monospace}.sample .reading-copy{padding:15px 20px;font-size:12px;line-height:2.2}.sample .reading-copy p{margin:0 0 38px}.sample .reading-copy b{font:9px monospace}.sample .reading-stroke{stroke-dasharray:169.646;stroke-dashoffset:169.646}',(p,c)=>{c.root.querySelector('.reading-stroke').style.strokeDashoffset=String(169.646*(1-p));c.root.querySelector('.reading-value').textContent=String(Math.round(p*100))},'https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Attribute/stroke-dashoffset');
// 11. Native scroll snapping keeps complete scenes aligned.
add('snap-story','Scroll-snap storytelling','一場面ずつ切り替える','スクロールの止まりどころをそろえ、各場面を見やすくします。','短いストーリーや、少数のスライド。','ブラウザ標準のscroll-snapを使います。下のスライダーからも場面を選べます。',['スナップ','snap','物語','スライド'],shell('<section class="snap-page"><small>01 / DISCOVER</small><b>See it.</b><p>見つける。</p></section><section class="snap-page"><small>02 / UNDERSTAND</small><b>Feel it.</b><p>違いを体感する。</p></section><section class="snap-page"><small>03 / CREATE</small><b>Make it.</b><p>自分の表現へ。</p></section>',{native:true,portClass:'snap-port'}),'.sample .snap-port{scroll-snap-type:y mandatory}.sample .snap-page{height:var(--vh);scroll-snap-align:start;scroll-snap-stop:always;padding:20px;display:flex;flex-direction:column;justify-content:center;gap:8px;background:#ebebeb}.sample .snap-page:nth-child(2){background:#b3b3b3}.sample .snap-page:nth-child(3){background:#373737;color:white}.sample .snap-page small{font:8px monospace;letter-spacing:.14em}.sample .snap-page b{font:900 39px Arial;letter-spacing:-.06em}.sample .snap-page p{margin:0;font-size:11px}',()=>{},'https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/scroll-snap-type');
// 12. Direction, rather than absolute progress, controls navigation visibility.
add('direction-header','Scroll-aware header','上へ戻すと現れるヘッダー','下へ読むと隠れ、上へ戻ると現れるヘッダーです。','読む領域を広く保ちながら、移動手段を残したい場面。','位置ではなく、直前からのスクロール方向を見ています。見本の中で試せます。',['ヘッダー','方向','header','ナビゲーション','隠れる'],shell('<header class="direction-head"><b>good.</b><span>MENU ☰</span></header><article class="direction-copy"><h3>読み進める。<br>少し、戻る。</h3><p>下へスクロールすると、上のヘッダーが隠れます。</p><i></i><p>上へ少し戻すと、ヘッダーが現れます。</p><i></i><p>画面全体ではなく、この見本の中だけで動作します。</p></article>',{native:true}),'.sample .direction-head{position:sticky;top:0;z-index:3;padding:10px 13px;display:flex;justify-content:space-between;align-items:center;background:#363636;color:white;transition:transform .2s ease}.sample .direction-head b{font:900 23px Arial;letter-spacing:-.07em}.sample .direction-head span{font:8px monospace}.sample .direction-copy{padding:8px 18px 30px;font-size:11px;line-height:1.9}.sample .direction-copy h3{font-size:23px;line-height:1.2;letter-spacing:-.05em}.sample .direction-copy p{margin:20px 0 55px}.sample .direction-copy i{display:block;height:60px;border-radius:6px;background:repeating-linear-gradient(0deg,#d7d7d7 0 1px,transparent 1px 12px)}.sample .motion-reduced .direction-head{transition:none}',(p,c)=>{const h=c.root.querySelector('.direction-head');if(p<.02||c.delta<-.5)h.style.transform='translateY(0)';else if(c.delta>.5)h.style.transform='translateY(-110%)'},scrollSource);
// 13. Native sticky cards remain layered as later cards arrive.
add('stacked-cards','Stacked sticky cards','カードが積み重なる','後から来るカードが前のカードの上へ重なり、層をつくります。','工程や、章ごとにまとまった情報。','カードごとにstickyの止まる位置を少しずつずらしています。',['カード','stack','重なる','sticky','積み重なる'],shell('<div class="card-stack"><section class="stack-card" style="--i:0"><small>01 / OBSERVE</small><b>見つける。</b><span>○</span></section><section class="stack-card" style="--i:1"><small>02 / EXPERIMENT</small><b>試してみる。</b><span>□</span></section><section class="stack-card" style="--i:2"><small>03 / MAKE</small><b>つくってみる。</b><span>△</span></section><div class="stack-tail"></div></div>',{native:true}),'.sample .card-stack{padding:7px}.sample .stack-card{position:sticky;top:calc(7px + var(--i)*11px);height:calc(var(--vh)*.82);min-height:95px;margin-bottom:24px;background:#e9e9e9;border:1px solid #a7a7a7;border-radius:8px;display:flex;flex-direction:column;justify-content:center;gap:10px;padding:17px;z-index:calc(1 + var(--i))}.sample .stack-card:nth-child(2){background:#b9b9b9}.sample .stack-card:nth-child(3){background:#404040;color:white}.sample .stack-card small{font:8px monospace}.sample .stack-card b{font-size:19px;letter-spacing:-.04em}.sample .stack-card span{position:absolute;right:18px;bottom:14px;font-size:28px}.sample .stack-tail{height:calc(var(--vh)*.6)}.sample .motion-reduced .stack-card{position:relative;top:0}',()=>{},stickySource);
// 14. Separate glyphs travel away from a shared center.
add('split-typography','Scroll-spread typography','文字を左右へほどく','文字を一つずつ分け、中心から左右へ広げます。','短い見出しや、印象を変えるタイポグラフィ。','読みやすさが必要な文章とは分けて使います。見本は一つの単語を分割しています。',['文字','split text','広がる','タイポグラフィ','分解'],shell('<div class="split-word" aria-label="GOOD"><i>G</i><i>O</i><i>O</i><i>D</i></div><span class="split-caption">A WORD, FOUR FORMS.</span>'),'.sample .split-word{display:flex;align-items:center;justify-content:center;gap:1px}.sample .split-word i{font:900 48px Arial;letter-spacing:-.08em;font-style:normal;display:block}.sample .split-caption{position:absolute;bottom:24px;font:8px monospace;letter-spacing:.15em;color:#777}',(p,c)=>{const a=c.reduced?0:p;[...c.root.querySelectorAll('.split-word i')].forEach((n,i)=>{const d=i-1.5;n.style.transform=`translate(${d*a*25}px,${Math.abs(d)*a*8}px) rotate(${d*a*8}deg)`;n.style.opacity=String(1-a*.2)})},transformSource);
// 15. Progress is measured through the viewport, not through the whole scroll range.
add('view-progress','Viewport progress','見える位置に連動する','要素が枠へ入り、中央を通り、出ていく位置に応じて変化します。','要素ごとに、画面内での登場と退出を制御したい場面。','要素と見本枠の座標から進み具合を計算しています。スクロール全体の進捗とは別です。',['view timeline','表示位置','viewport','登場','退出'],shell('<div class="view-lead">SCROLL TO THE OBJECT ↓</div><div class="view-subject"><b>in<br>view.</b><small>ELEMENT PROGRESS</small></div><div class="view-trail">↑ 通り過ぎると、小さくなる</div>',{native:true}),'.sample .view-lead{height:calc(var(--vh)*.62);padding:18px;font:8px monospace;color:#777}.sample .view-subject{width:80%;height:calc(var(--vh)*.78);min-height:90px;margin:0 auto;display:flex;flex-direction:column;justify-content:center;align-items:center;background:#424242;color:#fff;border-radius:8px;gap:10px;transform:scale(.75);opacity:.4}.sample .view-subject b{font:900 35px Arial;line-height:.9;letter-spacing:-.06em}.sample .view-subject small{font:8px monospace;letter-spacing:.09em}.sample .view-trail{height:calc(var(--vh)*1.2);padding:28px;text-align:center;font-size:10px;color:#777}',(p,c)=>{const n=c.root.querySelector('.view-subject');n.style.transform='none';const r=n.getBoundingClientRect(),v=c.port.getBoundingClientRect(),q=c.clamp((v.bottom-r.top)/(v.height+r.height)),presence=Math.sin(Math.PI*q);n.style.transform=`scale(${c.reduced?1:.75+presence*.25})`;n.style.opacity=String(c.reduced?1:.35+presence*.65)},'https://developer.mozilla.org/en-US/docs/Web/API/Element/getBoundingClientRect');
// 16. Velocity makes the type lean; the position alone does not determine the shape.
add('velocity-skew','Scroll-velocity skew','速さで傾く文字','スクロールの速さと向きに応じて文字が傾き、止めると元へ戻ります。','動きの勢いを感じさせる短い装飾。','位置ではなく移動量と経過時間を使います。ゆっくり・速く、両方試してみてください。',['速度','velocity','skew','傾く','慣性'],shell('<div class="speed-word">flow.</div><span class="speed-caption">ゆっくり。速く。止めて。</span>'),'.sample .speed-word{font:900 60px Arial;letter-spacing:-.08em;transform-origin:center center}.sample .speed-caption{position:absolute;bottom:24px;font-size:9px;color:#666}',(p,c)=>{const word=c.root.querySelector('.speed-word');c.state.animation?.cancel();word.style.transform='skewX(0deg)';if(c.reduced||Math.abs(c.velocity)<.01)return;const angle=c.clamp(c.velocity*7,-14,14);c.state.animation=c.track(word.animate([{transform:`skewX(${-angle}deg)`},{transform:'skewX(0deg)'}],{duration:300,easing:'cubic-bezier(.16,1,.3,1)'}))},scrollSource);
